using AbiRead=bool(*)(void*,const void*,size_t);
inline bool verifyNativeAbi(AbiRead read){
    if(!read)return false;
    for(const auto&s:NativeSignatures){unsigned char found[16]{};
        if(!read(found,reinterpret_cast<const void*>(s.address),s.count)||std::memcmp(found,s.bytes,s.count))return false;}
    return true;
}
